      "id": "kakawira_c1_lesson_04",
      "title": "Oratoria en el Consejo de Ancianos de Cacaopera",
      "level": "C1",
      "category": "Retórica Indígena",
      "summary": "Discurso ceremonial para la toma de decisiones comunitarias.",
